def add_todo(todos: list[dict[str, object]], item: str) -> list[dict[str, object]]:
    """Add a todo item to the list and return the updated list."""
    todos.append({"text": item, "done": False})
    return todos


def complete_todo(todos: list[dict[str, object]], item: str) -> list[dict[str, object]]:
    """Mark a todo item as done and return the updated list."""
    for todo in todos:
        if todo["text"] == item:
            todo["done"] = True
            break
    return todos

import json


def save_todos(todos, path):
    """Write the todos list to path as JSON."""
    with open(path, "w") as f:
        json.dump(todos, f)


def load_todos(path):
    """Read a todos list from a JSON file at path."""
    with open(path) as f:
        return json.load(f)

